insert into public.word_senses (id, stable_key, word_id, module_id, category_id, meaning_en, meaning_zh, usage_note)
values
  ('fe1e9b42-9b5e-50a5-97ea-1b56acfb33e2', 'medical_english:symptoms:symptom:noun', '81195ae6-3ee1-5c5a-82e4-158ab477cfeb', '52d53e9d-b343-50d9-b0d8-059b2540f890', '58a9e7bc-4a47-5465-bf8e-a6312ab0df40', 'a change the patient feels or reports, not something the examiner finds', '症状（患者主观感到的）', '患者自己感到或讲述的才写 symptom。医生查到的是 sign。发热若只有主诉、尚未测温，先当症状记。'),
  ('d16136af-61f7-50d5-b6ad-6f1ccf8503b7', 'medical_english:signs:sign:noun', 'a6642463-5c60-53aa-b168-3044ace730a4', '52d53e9d-b343-50d9-b0d8-059b2540f890', '55cae568-79b1-56b4-89eb-8a24ade01c2a', 'an objective finding the examiner can see, feel, or measure', '体征（检查者客观发现的）', '查体或仪器测到的才写 sign。患者只说“胸口痛”是 symptom；听到杂音才是 sign。'),
  ('0dd1f245-6bb9-5fc0-9fae-7c0c5dfac777', 'medical_english:diagnosis:diagnose:verb', '53605c79-39bc-50ea-891a-ed79c84ed9b5', '52d53e9d-b343-50d9-b0d8-059b2540f890', '418fd2cc-1b52-52cd-a6b1-460558fc0fad', 'to name the illness after enough history, exam, and tests', '诊断出；作出诊断', '证据够了才能写 diagnosed。还在排查时写 suspected 或 working diagnosis，不要提前写成已确诊。'),
  ('3ddcb191-754e-56f8-929e-f8408d2cf41f', 'medical_english:anatomy:artery:noun', '3a382a00-c328-5ec1-aabd-3894548fabbf', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'f2f95a33-ad8a-576c-9ec4-563e8ad57801', 'a vessel that carries blood away from the heart', '动脉', '从心脏向外送血的管子才写 artery。回心的是 vein。摸脉搏摸的是动脉，不是静脉。'),
  ('4700540e-e207-5107-b146-2af168acd9b4', 'medical_english:anatomy:vein:noun', '3a6f7735-5a82-58f3-a45b-58e2e4134948', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'f2f95a33-ad8a-576c-9ec4-563e8ad57801', 'a vessel that carries blood back toward the heart', '静脉', '把血送回心脏的管子才写 vein。抽血、输液常走静脉。不要把摸到的搏动血管写成 vein。'),
  ('12de08a9-5c46-579b-b2d4-0b258953a573', 'medical_english:clinical_expressions:acute:adjective', '97a6ae26-03a5-5989-bca9-e68d0c0803f7', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'a482bbf8-c44c-590c-a328-562f923f69ae', 'sudden or short-lived, as opposed to long-standing chronic illness', '急性的', '起病急或病程短才写 acute。拖了几个月的是 chronic。急性不等于一定危重。'),
  ('55666f7d-6414-52f1-b4e2-1670b1f591c9', 'medical_english:clinical_expressions:chronic:adjective', '19ff37f9-6420-5a21-8d18-8b277fdd9182', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'a482bbf8-c44c-590c-a328-562f923f69ae', 'long-lasting or repeatedly returning, as opposed to acute', '慢性的', '病程长或反复迁延才写 chronic。刚发作几小时不要写 chronic。慢性也不等于不严重。'),
  ('da84c665-e5ae-5e8d-8d10-af61e74dfcad', 'medical_english:morphology:anatomy:noun', '307820ab-c341-5d38-bdaa-4549b488b6e1', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'the study of body structure (ana- up/apart + -tomy cutting)', '解剖学', 'ana- 是拆开，-tomy 是切：靠切开看结构。词根能提醒“看构造”，但局部解剖课不等于会做手术，不能只靠构词。'),
  ('b4f003d1-7ac7-5bca-b7e2-0ebf39b6c64c', 'medical_english:morphology:embryology:noun', 'c41ac7bd-234f-59c1-9833-8f75d91ea6f3', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'the study of the developing embryo (embryo- unborn + -logy study)', '胚胎学', 'embryo- 是胚胎，-logy 是学科。词根是“研究未出生阶段”，不能只靠构词把发育异常写成具体畸形病名。'),
  ('2ada0078-d3e8-5cff-b3a1-5fb177820b46', 'medical_english:morphology:histology:noun', 'c3ebfaee-cda6-5e81-bfb0-a4fcaf56f656', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'the study of tissues under the microscope (hist- tissue + -logy study)', '组织学', 'hist- 是组织，-logy 是学科。词根是看组织切片，不等于病理诊断；炎症还是肿瘤要另看，不能只靠构词。'),
  ('6734d52b-3ce1-5141-8989-5dc1ffd2ed53', 'medical_english:morphology:hematology:noun', '5df19b3f-0751-511d-af7f-f9f64c89dcc9', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'the study of blood and blood-forming tissues (hemat- blood + -logy study)', '血液学', 'hemat- 是血，-logy 是学科。词根能猜“和血有关”，但贫血、白血病还是凝血病不能只靠构词定病。'),
  ('fd072c1c-aade-5b8b-8e79-24e7a26b21d5', 'medical_english:morphology:immunology:noun', '3d870c05-b490-5681-946e-e828dec55bfd', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'the study of the immune system (immun- exempt/protected + -logy study)', '免疫学', 'immun- 是免除、不受侵害，-logy 是学科。词根是防御系统，过敏、感染还是自身免疫不能只靠构词分开。'),
  ('810b8567-2d0f-5d97-a58e-ec90264f22ff', 'medical_english:morphology:cytology:noun', 'de821111-dba9-5a9f-bba7-6c3a3b00d99c', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'the study of cells, often from a smear or fluid (cyt- cell + -logy study)', '细胞学', 'cyt- 是细胞，-logy 是学科。涂片看细胞不等于组织学切片，更不等于癌症确诊，不能只靠构词。'),
  ('14f1f764-ca92-5cc3-8fd0-7e069dcf1a16', 'medical_english:morphology:physiology:noun', '1b90028a-e685-542f-b900-f6f2ebdc02db', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'the study of how the body functions (physio- nature/function + -logy study)', '生理学', 'physio- 是功能、自然运转，-logy 是学科。词根是“身体怎么工作”，不是解剖结构，更不能只靠构词当病名。'),
  ('8a384648-af3d-5daf-8c75-f5098c8b9b0c', 'medical_english:morphology:endocrinology:noun', '47e700f3-fd2b-548e-91cb-4b6cb48514c8', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'the study of glands that secrete hormones into blood (endo- inside + crin- secrete + -logy study)', '内分泌学', 'endo- 是向内，crin- 是分泌，-logy 是学科：激素入血。词根能猜学科范围，甲亢还是糖尿病不能只靠构词。'),
  ('fd26516d-662d-56ac-ac95-adb9c60f372a', 'medical_english:morphology:psychology:noun', '829d8bdd-d30e-50b4-8bb6-c187ee530daa', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'the study of mind and behavior (psych- mind + -logy study)', '心理学', 'psych- 是心智，-logy 是学科。词根是研究心理过程，不等于精神科诊断，更不能只靠构词给人贴病名。'),
  ('8c985879-0fad-5edb-971e-8e73d4aceff4', 'medical_english:morphology:pathology:noun', 'ffdd77fc-8cd9-5f02-83ec-2f2acd112cbe', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'the study of disease processes (path- disease + -logy study)', '病理学', 'path- 是疾病，-logy 是学科。词根是“研究生病过程”。口头说 pathology 有时只指化验科，不能只靠构词。'),
  ('200c970e-f950-5306-a506-69b5f794609e', 'medical_english:morphology:biology:noun', 'fcbc0afe-d555-5948-ba95-12c33027d7d1', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'the study of living things (bio- life + -logy study)', '生物学', 'bio- 是生命，-logy 是学科。词根很宽，细胞、遗传、生态都算；课堂说 medical biology 仍不能只靠构词当专科。'),
  ('6e694e91-b18f-5835-9f5e-3f4abd99eb28', 'medical_english:morphology:cardiovascular:adjective', '7c93a13e-d4d8-5ce4-8323-bc2d46872c83', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'relating to the heart and blood vessels (cardi- heart + vascul- vessel + -ar relating to)', '心血管的', 'cardi- 是心，vascul- 是血管。词根能圈出系统，心衰、冠心病还是血管炎不能只靠构词当成同一个病。'),
  ('0cc67e45-b36d-5357-91d6-1f47056ef7e4', 'medical_english:morphology:lymphatic:adjective', 'b936be29-e4c2-5ce5-95b4-f3296423a9a2', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'relating to lymph and its vessels or nodes (lymph- clear fluid + -atic relating to)', '淋巴的', 'lymph- 是淋巴液，-atic 表示相关。词根能指系统，淋巴结肿大原因很多，不能只靠构词写成淋巴瘤。'),
  ('ef281588-5c9f-5715-a535-51d5ed93a8c4', 'medical_english:morphology:circulatory:adjective', '8f8b50fa-0248-5e52-82a9-612025fbe369', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'relating to blood circulation (circul- go around + -atory relating to a process)', '循环的', 'circul- 是环行，-atory 表过程。词根是血液绕行全身。课堂常与心血管系统重叠，不能只靠构词区分两个术语。'),
  ('984d2b96-cb7d-5d3c-ba9c-35a60c968018', 'medical_english:morphology:respiratory:adjective', 'aa060236-6b0d-58cc-b752-db32e199db9e', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'relating to breathing (re- again + spir- breathe + -atory process)', '呼吸的', 're- 是再，spir- 是呼吸。词根是气体交换过程。气促、哮喘还是肺炎不能只靠构词写成同一种病。'),
  ('42dce195-608b-5510-bf80-243c267bb3f7', 'medical_english:morphology:urinary:adjective', 'b6401b26-048d-52f7-bd1d-c1ed30abcb5d', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'relating to urine and its pathway (urin- urine + -ary relating to)', '泌尿的', 'urin- 是尿，-ary 表相关。词根圈出肾到尿道的通路。尿频原因很多，不能只靠构词当成尿路感染。'),
  ('c27b01b4-a53f-5710-85a7-4c95d673208f', 'medical_english:morphology:endocrine:adjective', '75e8f80f-85bd-561e-9b94-1a7565988230', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'secreting hormones into the blood (endo- inside + crine secrete)', '内分泌的', 'endo- 是向内，crine 是分泌：激素入血，不是经导管排到体表。汗腺是外分泌，不能只靠构词混用。'),
  ('7ed01ee1-f314-5bb7-ac3f-6e17b82867d3', 'medical_english:morphology:reproductive:adjective', '6ae367ab-5268-5d83-969f-1e3f4d569a04', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'relating to producing offspring (re- again + product- bring forth + -ive relating to)', '生殖的', 're- 是再，product- 是产生。词根是生殖功能。课堂讲卵巢或睾丸时，不能只靠构词把所有盆腔痛写成生殖系统病。'),
  ('d8e6f5a7-016d-5288-b942-4350aeeb6026', 'medical_english:morphology:gastrointestinal:adjective', 'f2354d5e-edd7-584d-88df-41c665d2b42a', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'relating to the stomach and intestines (gastro- stomach + intestin- bowel + -al relating to)', '胃肠的', 'gastro- 是胃，intestin- 是肠。词根圈出消化管中段。呕吐、腹泻原因很多，不能只靠构词写成胃炎或肠炎。'),
  ('5fea806a-73d3-5abd-b3f2-0006990fdd3f', 'medical_english:morphology:stomatitis:noun', '7884104e-572c-51ba-b19d-37ac5c6ef418', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'inflammation of the mouth (stomat- mouth + -itis inflammation)', '口炎', 'stomat- 是口，-itis 是炎症。词根能猜口腔黏膜发炎，病毒、义齿还是营养缺乏不能只靠构词定因。'),
  ('cf208189-592d-59ce-890c-5016608fe8fc', 'medical_english:morphology:colitis:noun', '6f74f387-c804-540d-94e9-e2af42b4e9c5', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'inflammation of the colon (col- large intestine + -itis inflammation)', '结肠炎', 'col- 是结肠，-itis 是炎症。词根能猜大肠炎症，感染、缺血还是炎症性肠病不能只靠构词。'),
  ('a63364dc-9f43-5270-810e-92a565efa30d', 'medical_english:morphology:pathogen:noun', '9363620d-297c-59fd-8b6c-799bd1cbee4a', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'an organism that can cause disease (patho- disease + -gen that produces)', '病原体', 'patho- 是疾病，-gen 是产生者。词根是“能致病的东西”。定植菌不一定致病，不能只靠构词把培养阳性写成感染。'),
  ('7afb1e55-eca3-5198-8a10-00de6cecc4fd', 'medical_english:morphology:asymptomatic:adjective', '443864ae-dce6-529b-9f1b-9bd424e619d4', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'having no symptoms (a- without + symptom + -atic relating to)', '无症状的', 'a- 是没有，后面是 symptom。词根是患者没感到不适。无症状不等于没病，筛查阳性仍要另解释，不能只靠构词。'),
  ('4ff66f54-2dea-5efc-baa0-0761fda5ccda', 'medical_english:morphology:symptomatic:adjective', 'c12574f7-33cd-5fd4-9222-ffffbc01cd53', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'showing symptoms, or aimed at relieving them (symptom + -atic relating to)', '有症状的；对症的', '词根是“和症状有关”。symptomatic treatment 是对症，不是治因。有症状也不等于已确诊，不能只靠构词。'),
  ('4f55f05c-e608-5f96-8a9b-ee22db689400', 'medical_english:morphology:apnea:noun', 'ebf9df9d-8d6a-5b6c-9a62-f58124779666', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'a pause in breathing (a- without + -pnea breathing)', '呼吸暂停', 'a- 是没有，-pnea 是呼吸。词根是暂时不喘气。睡眠呼吸暂停和心跳骤停时的无呼吸不是同一回事，不能只靠构词。'),
  ('ef14b1d5-a00e-5c39-b21b-86d6ae2de28c', 'medical_english:morphology:atonia:noun', '4c9a1299-0fb8-51e7-9e66-7f1630286324', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'lack of muscle tone (a- without + ton- tone + -ia condition)', '张力缺失；弛缓', 'a- 是没有，ton- 是张力。词根是肌肉松软。睡眠期正常肌弛缓和病理软瘫不是一回事，不能只靠构词当诊断。'),
  ('5468170d-9465-5567-838c-b8a5e36c6216', 'medical_english:morphology:subacute:adjective', '4f0f447d-3611-5ec8-ac86-8989f124a3f1', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'between acute and chronic in time course (sub- under/less than + acute sudden)', '亚急性的', 'sub- 是低于、介于，acute 是急。词根是比急性慢、比慢性快。天数界限因病而异，不能只靠构词套用。'),
  ('c024a32f-9839-5a21-910e-bac44538e425', 'medical_english:morphology:epidemic:noun', 'fb31b360-8804-50ed-bcd6-cb752817d1c1', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'a sudden rise of cases in a community (epi- upon + dem- people + -ic relating to)', '流行；流行病', 'epi- 是在上，dem- 是人群。词根是疾病压在一群人身上。地方性流行是 endemic，全球大流行是 pandemic，不能只靠构词混用。'),
  ('ea910655-c361-5b51-90bc-42c300685d8b', 'medical_english:morphology:endemic:adjective', 'ca75e943-4738-5b92-a9df-eac4c2bf4ed7', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'always present in a particular place or people (en- in + dem- people + -ic relating to)', '地方性的；某地持续存在的', 'en- 是在内，dem- 是人群。词根是疾病常驻当地。突然暴发应写 epidemic，不能只靠构词把输入病例写成地方病。'),
  ('e9e4d315-965b-5bc6-9841-e91dc616fc75', 'medical_english:morphology:antigen:noun', '2d62c4e7-d9b6-5904-be6f-4d81f28e64e9', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'a molecule that can trigger an immune response (anti- against + -gen that produces)', '抗原', 'anti- 是对抗，-gen 是产生者：能引出抗体的东西。抗原阳性不等于正在生病，疫苗成分也是抗原，不能只靠构词。'),
  ('aca4631d-b369-56e3-a966-e29614bb70af', 'medical_english:morphology:antibody:noun', 'b558d8bd-40bb-5bc5-a3e7-22d25f4a2cec', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'an immune protein that binds a specific antigen (anti- against + body substance)', '抗体', 'anti- 是对抗，body 是这种蛋白。词根是“对抗异物的蛋白”。IgM 和 IgG 时间不同，不能只靠构词判断新发还是既往。'),
  ('64c47718-fe86-5831-800e-02655b81814a', 'medical_english:morphology:immunoglobulin:noun', '1f265ed9-0ac8-5f7e-89bf-73bf72fd8546', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'an antibody protein (immuno- immune + globulin globe-shaped protein)', '免疫球蛋白', 'immuno- 是免疫，globulin 是球形蛋白。IgG、IgA、IgM 功能不同，不能只靠构词把一项升高写成免疫缺陷或过敏。'),
  ('87ee9294-14b2-5160-aa88-60b18b0ffbf9', 'medical_english:morphology:phagocyte:noun', 'e091afa5-9045-516c-994c-5f7d4d8d74bc', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'a cell that engulfs particles or microbes (phago- eat + -cyte cell)', '吞噬细胞', 'phago- 是吃，-cyte 是细胞。词根是会吞颗粒的细胞。中性粒细胞和巨噬细胞都算，不能只靠构词指定哪一种。'),
  ('bb44bc2c-61a5-5698-a2e9-a9ab53d0ad9c', 'medical_english:morphology:degeneration:noun', 'bd3a428d-dcf3-5280-90eb-8ddc75f74217', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'progressive loss of normal cell or tissue quality (de- away + gener- kind/origin + -ation process)', '变性；退行性变', 'de- 是离开，gener- 是正常类型。词根是组织变差。关节退变和神经变性不是同一病，不能只靠构词当诊断。'),
  ('56fb982b-c55c-5108-a6ea-fdbfc1738a06', 'medical_english:morphology:malfunction:noun', '3f73cda4-323d-566e-a2b7-bf8ff36a7d4a', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'failure to work normally (mal- bad + function working)', '功能障碍；工作失常', 'mal- 是不好，function 是工作。词根是“工作出差错”。器官衰竭比 malfunction 更重，不能只靠构词升级病情。'),
  ('8d3efc58-df59-55a4-a307-2e5362a6d613', 'medical_english:morphology:malnutrition:noun', 'a5b8d10c-3d8e-5ef6-b223-34bdf0b701b5', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'poor nutrition from too little, too much, or unbalanced intake (mal- bad + nutrition nourishment)', '营养不良', 'mal- 是不好，nutrition 是营养。词根是营养状态差，包括热量不足或比例失衡。体瘦不等于此诊断，不能只靠构词。'),
  ('1cc9ba6a-80a6-5211-9375-0ba8d27cbe8a', 'medical_english:morphology:sublingual:adjective', 'f56a91e1-609c-56d8-86c3-d451b06c1f61', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'under the tongue (sub- under + lingu- tongue + -al relating to)', '舌下的', 'sub- 是在下，lingu- 是舌。词根是舌下给药或舌下腺。吞下去的口服药不是 sublingual，不能只靠构词。'),
  ('0f4b8699-00b9-5028-a357-5fc67676f1b0', 'medical_english:morphology:epiglottis:noun', 'dc36a0f8-f555-51ec-b56c-92f565536840', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'the flap above the glottis that helps keep food out of the airway (epi- upon + glottis voice opening)', '会厌', 'epi- 是在上，glottis 是声门。词根是盖在声门上的结构。会厌炎是另一诊断，不能只靠构词把吞咽不适写成会厌炎。'),
  ('d72695cf-7772-530c-a44f-223b6ce6a90d', 'medical_english:morphology:peristalsis:noun', '49487d9d-da60-52bc-9d0f-e8b3b7f8d9de', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'wave-like squeezing that moves contents along a tube (peri- around + stalsis constriction)', '蠕动', 'peri- 是环绕，stalsis 是缩窄。词根是管壁环形推进。肠鸣活跃不等于正常蠕动，梗阻时不能只靠构词判断。'),
  ('a1a7f106-1e1e-5a47-bc75-758974012b34', 'medical_english:morphology:ingestion:noun', 'f1936a7c-9d38-55e0-9505-b30ceabf7f28', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'the act of taking food or a substance into the mouth (in- in + gest- carry + -ion act)', '摄入；经口进入', 'in- 是进入，gest- 是运送。词根是把东西送进口。吸入是 inhalation，静脉给药不是 ingestion，不能只靠构词。'),
  ('f666d711-2e73-58ab-bdf9-c648b98bac57', 'medical_english:morphology:cardiac:adjective', '65e1e4f9-f9e5-5cef-af7b-9847b293258f', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'relating to the heart (cardi- heart + -ac relating to)', '心脏的', 'cardi- 是心，-ac 表相关。词根能指定器官。胸痛不必是 cardiac，胃或肺来源也常见，不能只靠构词。'),
  ('178fe9ff-2876-5251-9131-b0092a3de242', 'medical_english:morphology:paralysis:noun', '548076d5-a46e-51eb-93f2-3c572d1bafe9', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'e769a684-fd45-5829-b213-e6c95d306b6c', 'loss of the ability to move a part of the body (para- beside/abnormal + -lysis loosening)', '瘫痪', 'para- 是异常，-lysis 是松解。词根提示运动能力松开。无力和完全不能动程度不同，不能只靠构词写成脊髓病。')
insert into public.contexts (id, stable_key, word_sense_id, context_sentence, target_text, plain_english_paraphrase, sentence_translation_zh, collocations, context_genre, source_type, source_title, source_url, doi, pmid)
values
  ('9f9fedb1-66b1-569d-b8a3-1f772f24fa4e', 'medical_english:symptoms:symptom:noun:med-symptoms-symptom-001', 'fe1e9b42-9b5e-50a5-97ea-1b56acfb33e2', 'Fever was the first symptom, followed by a dry cough on day two.', 'symptom', 'A high temperature was the first thing she felt, and a dry cough came the next day.', '发热是首发症状，第二日出现干咳。', array['first symptom', 'presenting symptom', 'symptom onset']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('1d5c887f-3383-5b1c-9d8f-304746cfcabb', 'medical_english:signs:sign:noun:med-signs-sign-001', 'd16136af-61f7-50d5-b6ad-6f1ccf8503b7', 'A new murmur was the only abnormal sign on examination.', 'sign', 'A newly heard heart sound was the only unusual finding when doctors examined her.', '新出现的杂音是查体中唯一异常体征。', array['vital signs', 'physical sign', 'no focal signs']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('ba05d0f8-c16a-5187-b4bc-7ae7841950fe', 'medical_english:diagnosis:diagnose:verb:med-diagnosis-diagnose-001', '0dd1f245-6bb9-5fc0-9fae-7c0c5dfac777', 'Community-acquired pneumonia was diagnosed after the chest radiograph.', 'diagnosed', 'Doctors named the illness as pneumonia caught outside hospital once the chest X-ray was seen.', '胸片完成后诊断为社区获得性肺炎。', array['was diagnosed with', 'diagnose early', 'difficult to diagnose']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('8d616fe4-6f26-5ebc-b770-8adfd3803f8f', 'medical_english:anatomy:artery:noun:med-anatomy-artery-001', '3ddcb191-754e-56f8-929e-f8408d2cf41f', 'The pulse is felt where an artery lies close to the skin.', 'artery', 'You can feel a pulse at places where a vessel leaving the heart runs near the surface.', '动脉靠近皮肤处可以摸到脉搏。', array['radial artery', 'blocked artery', 'artery wall']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('693e4ed7-0d86-54bf-889c-50250013230e', 'medical_english:anatomy:vein:noun:med-anatomy-vein-001', '4700540e-e207-5107-b146-2af168acd9b4', 'Blood was drawn from a vein in the left arm.', 'vein', 'A sample was taken from a vessel in the left arm that returns blood to the heart.', '从左臂静脉抽血。', array['peripheral vein', 'vein puncture', 'dilated vein']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('a9d81724-338b-5fb3-a677-9e0e1d90496c', 'medical_english:clinical_expressions:acute:adjective:med-clinical-acute-001', '12de08a9-5c46-579b-b2d4-0b258953a573', 'She was admitted for acute abdominal pain lasting six hours.', 'acute', 'She came into hospital because belly pain had started suddenly and had lasted six hours.', '她因持续六小时的急性腹痛入院。', array['acute pain', 'acute infection', 'acute onset']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('1c555dcd-e3b2-590c-bbfc-e2f8800ec07e', 'medical_english:clinical_expressions:chronic:adjective:med-clinical-chronic-001', '55666f7d-6414-52f1-b4e2-1670b1f591c9', 'His chronic cough had lasted more than eight weeks.', 'chronic', 'The cough had been present for more than eight weeks instead of a short attack.', '他的慢性咳嗽已持续八周以上。', array['chronic cough', 'chronic disease', 'chronic pain']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('3be568dc-fd72-53da-a158-b013471ef7b5', 'medical_english:morphology:anatomy:noun:med-morphology-anatomy-001', 'da84c665-e5ae-5e8d-8d10-af61e74dfcad', 'First-year students learn the anatomy of the heart before they hear murmurs.', 'anatomy', 'Beginners study how the heart is built before they learn to hear extra heart sounds.', '一年级学生先学心脏解剖，再听杂音。', array['gross anatomy', 'anatomy of the heart', 'anatomy course']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('9f1629a2-099d-556a-b6e7-9a5163ea8257', 'medical_english:morphology:embryology:noun:med-morphology-embryology-001', 'b4f003d1-7ac7-5bca-b7e2-0ebf39b6c64c', 'A short embryology lecture explains why some heart defects form in the first weeks.', 'embryology', 'The study of early development helps show why some heart problems start in the first weeks.', '胚胎学解释部分心脏缺陷为何在最初几周形成。', array['human embryology', 'embryology lecture', 'clinical embryology']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('a1a5390a-2e03-5cb2-9e9e-3525d44ca5f3', 'medical_english:morphology:histology:noun:med-morphology-histology-001', '2ada0078-d3e8-5cff-b3a1-5fb177820b46', 'In histology labs, students learn to recognize epithelium and connective tissue.', 'histology', 'Microscope classes help students tell lining tissue from the supporting tissue around it.', '组织学实验课教学生辨认上皮和结缔组织。', array['histology lab', 'normal histology', 'histology slide']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('33a37260-5c7a-573c-bc9d-0770ffcf5ccf', 'medical_english:morphology:hematology:noun:med-morphology-hematology-001', '6734d52b-3ce1-5141-8989-5dc1ffd2ed53', 'The hematology course covers red cells, white cells, platelets, and clotting.', 'hematology', 'This subject looks at the cells in blood and at how blood forms clots.', '血液学涵盖红细胞、白细胞、血小板和凝血。', array['clinical hematology', 'hematology report', 'hematology clinic']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('f776b05b-d800-5720-8891-ab7866e15301', 'medical_english:morphology:immunology:noun:med-morphology-immunology-001', 'fd072c1c-aade-5b8b-8e79-24e7a26b21d5', 'Basic immunology explains how antibodies recognize a foreign antigen.', 'immunology', 'This field explains how defense proteins notice a marker that does not belong to the body.', '免疫学解释抗体如何识别外来抗原。', array['basic immunology', 'transplant immunology', 'immunology test']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('1fbf108b-968d-528e-a083-dae0713620b7', 'medical_english:morphology:cytology:noun:med-morphology-cytology-001', '810b8567-2d0f-5d97-a58e-ec90264f22ff', 'Sputum cytology was ordered to look for abnormal lung cells.', 'cytology', 'A lab test of coughed-up mucus was requested to inspect the lung cells themselves.', '送检痰细胞学以寻找异常肺细胞。', array['sputum cytology', 'cytology smear', 'negative cytology']::text[], 'laboratory_report', 'original_example', null, null, null, null),
  ('fbf97bba-a57c-53b7-aeb5-2faf21adb586', 'medical_english:morphology:physiology:noun:med-morphology-physiology-001', '14f1f764-ca92-5cc3-8fd0-7e069dcf1a16', 'A physiology class covers how the kidney filters blood and makes urine.', 'physiology', 'The function course explains how the kidney cleans blood and produces urine.', '生理课讲解肾脏如何滤过血液并生成尿液。', array['human physiology', 'pathologic physiology', 'physiology exam']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('d3019ee9-f204-5d58-a626-504ce8244686', 'medical_english:morphology:endocrinology:noun:med-morphology-endocrinology-001', '8a384648-af3d-5daf-8c75-f5098c8b9b0c', 'Most endocrinology clinics manage thyroid, adrenal, and insulin disorders.', 'endocrinology', 'Hormone clinics commonly treat problems of the thyroid, adrenal glands, and insulin.', '内分泌门诊常处理甲状腺、肾上腺和胰岛素相关疾病。', array['pediatric endocrinology', 'endocrinology consult', 'endocrinology ward']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('9bf29342-36f7-5bfa-8554-31004db63411', 'medical_english:morphology:psychology:noun:med-morphology-psychology-001', 'fd26516d-662d-56ac-ac95-adb9c60f372a', 'Medical psychology helps students talk with frightened patients.', 'psychology', 'Training about the mind helps students speak with patients who are scared.', '医学心理学帮助学生与恐惧的患者交谈。', array['medical psychology', 'health psychology', 'psychology of pain']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('1ceef864-9077-5ca3-be13-4b2a2b478bf2', 'medical_english:morphology:pathology:noun:med-morphology-pathology-001', '8c985879-0fad-5edb-971e-8e73d4aceff4', 'General pathology describes how inflammation damages tissue after infection.', 'pathology', 'The disease-process course explains how swelling after infection can harm tissue.', '病理学描述感染后炎症如何损伤组织。', array['general pathology', 'surgical pathology', 'pathology report']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('aa08dc71-1e68-5f61-8e53-2b8a0fa79f36', 'medical_english:morphology:biology:noun:med-morphology-biology-001', '200c970e-f950-5306-a506-69b5f794609e', 'Cell biology is the starting point for later histology and physiology.', 'biology', 'The study of living cells comes before later courses on tissues and body function.', '细胞生物学是后续组织学和生理学的起点。', array['cell biology', 'human biology', 'biology textbook']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('e7e5cd47-da1c-5d1a-993d-a0839c2719c4', 'medical_english:morphology:cardiovascular:adjective:med-morphology-cardiovascular-001', '6e694e91-b18f-5835-9f5e-3f4abd99eb28', 'The cardiovascular system includes the heart, arteries, veins, and capillaries.', 'cardiovascular', 'The heart-and-vessel system covers the pump plus the tubes that carry blood.', '心血管系统包括心脏、动脉、静脉和毛细血管。', array['cardiovascular system', 'cardiovascular disease', 'cardiovascular exam']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('1caa6b64-1ccc-5fb0-aedd-4b9155aa72aa', 'medical_english:morphology:lymphatic:adjective:med-morphology-lymphatic-001', '0cc67e45-b36d-5357-91d6-1f47056ef7e4', 'The lymphatic system returns fluid to the blood and helps immune defense.', 'lymphatic', 'The lymph network sends leftover fluid back into blood and supports immune defense.', '淋巴系统把组织液送回血液，并参与免疫防御。', array['lymphatic system', 'lymphatic vessel', 'lymphatic drainage']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('52f3b388-072d-55e0-988d-452d15876f3e', 'medical_english:morphology:circulatory:adjective:med-morphology-circulatory-001', 'ef281588-5c9f-5715-a535-51d5ed93a8c4', 'The circulatory system moves oxygen and nutrients to the tissues.', 'circulatory', 'The circulating-blood system carries oxygen and food substances out to the tissues.', '循环系统把氧和营养送到组织。', array['circulatory system', 'circulatory failure', 'circulatory shock']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('bec240bb-cd67-561c-ae26-02d60fa4c537', 'medical_english:morphology:respiratory:adjective:med-morphology-respiratory-001', '984d2b96-cb7d-5d3c-ba9c-35a60c968018', 'The respiratory system brings oxygen in and expels carbon dioxide.', 'respiratory', 'The breathing system takes oxygen in and sends carbon dioxide out.', '呼吸系统吸入氧气并排出二氧化碳。', array['respiratory system', 'respiratory rate', 'respiratory infection']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('6263d800-ad81-5435-a05c-a978821445aa', 'medical_english:morphology:urinary:adjective:med-morphology-urinary-001', '42dce195-608b-5510-bf80-243c267bb3f7', 'The urinary system includes the kidneys, ureters, bladder, and urethra.', 'urinary', 'The urine pathway includes the kidneys, the tubes down to the bladder, and the exit tube.', '泌尿系统包括肾、输尿管、膀胱和尿道。', array['urinary system', 'urinary tract', 'urinary output']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('4d7f0200-228a-514f-bd0a-abc53bdaaede', 'medical_english:morphology:endocrine:adjective:med-morphology-endocrine-001', 'c27b01b4-a53f-5710-85a7-4c95d673208f', 'The endocrine system uses hormones to regulate growth and metabolism.', 'endocrine', 'The inward-secreting gland system uses blood-borne messengers to control growth and energy use.', '内分泌系统用激素调节生长和代谢。', array['endocrine system', 'endocrine gland', 'endocrine disorder']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('953746b8-dac9-57af-b3ce-2c23726f6a06', 'medical_english:morphology:reproductive:adjective:med-morphology-reproductive-001', '7ed01ee1-f314-5bb7-ac3f-6e17b82867d3', 'The reproductive system includes the ovaries, uterus, and testes.', 'reproductive', 'The system for having children includes the ovaries, uterus, and testes.', '生殖系统包括卵巢、子宫和睾丸。', array['reproductive system', 'reproductive age', 'reproductive health']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('7ab98d82-8c4d-533a-95b6-51e6565b9cdf', 'medical_english:morphology:gastrointestinal:adjective:med-morphology-gastrointestinal-001', 'd8e6f5a7-016d-5288-b942-4350aeeb6026', 'The gastrointestinal tract runs from the mouth to the rectum.', 'gastrointestinal', 'The stomach-and-bowel tube starts at the mouth and ends at the rectum.', '胃肠道从口腔延伸到直肠。', array['gastrointestinal tract', 'gastrointestinal bleeding', 'gastrointestinal symptoms']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('8fdee322-7d38-5e40-bb43-2dfada7c172a', 'medical_english:morphology:stomatitis:noun:med-morphology-stomatitis-001', '5fea806a-73d3-5abd-b3f2-0006990fdd3f', 'Painful stomatitis made it hard for the patient to eat solid food.', 'stomatitis', 'A sore, inflamed mouth made chewing solid food difficult.', '疼痛性口炎使患者难以进固体食物。', array['oral stomatitis', 'aphthous stomatitis', 'severe stomatitis']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('2e5fb9f8-b4a3-523d-b876-ca58d84690db', 'medical_english:morphology:colitis:noun:med-morphology-colitis-001', 'cf208189-592d-59ce-890c-5016608fe8fc', 'Bloody diarrhea raised concern for infectious colitis.', 'colitis', 'Loose stools with blood made doctors worry the large bowel was inflamed by infection.', '血性腹泻使人担心感染性结肠炎。', array['ulcerative colitis', 'infectious colitis', 'ischemic colitis']::text[], 'case_report', 'original_example', null, null, null, null),
  ('650b9d9d-8746-5957-ade1-efc8c9b10682', 'medical_english:morphology:pathogen:noun:med-morphology-pathogen-001', 'a63364dc-9f43-5270-810e-92a565efa30d', 'Hand washing reduces the spread of a common respiratory pathogen.', 'pathogen', 'Washing hands lowers the chance of passing along a germ that can cause a breathing illness.', '洗手可减少常见呼吸道病原体的传播。', array['bacterial pathogen', 'identify the pathogen', 'opportunistic pathogen']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('a9c225d5-70bc-55ac-b3ec-2ccd2534efbf', 'medical_english:morphology:asymptomatic:adjective:med-morphology-asymptomatic-001', '7afb1e55-eca3-5198-8a10-00de6cecc4fd', 'The infection was asymptomatic and found only on routine testing.', 'asymptomatic', 'The person had no complaints; the infection showed up only on a routine test.', '感染并无症状，只在常规检测中发现。', array['asymptomatic infection', 'remain asymptomatic', 'asymptomatic carrier']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('3dfb264b-d33a-569a-8253-01caad63cb4a', 'medical_english:morphology:symptomatic:adjective:med-morphology-symptomatic-001', '4ff66f54-2dea-5efc-baa0-0761fda5ccda', 'Only symptomatic patients were advised to stay home and watch for worsening breath.', 'symptomatic', 'People who already had complaints were told to remain home and notice if breathing got worse.', '有症状者被建议居家，并观察呼吸是否加重。', array['symptomatic patient', 'symptomatic treatment', 'become symptomatic']::text[], 'clinical_guideline', 'original_example', null, null, null, null),
  ('6eba018b-f96a-55ad-a5eb-2309b1f3e045', 'medical_english:morphology:apnea:noun:med-morphology-apnea-001', '4f55f05c-e608-5f96-8a9b-ee22db689400', 'Witnesses reported a short spell of apnea before the infant cried again.', 'apnea', 'People who were there said the baby stopped breathing briefly and then cried again.', '目击者称婴儿在再次哭出声前有短暂呼吸暂停。', array['sleep apnea', 'episode of apnea', 'apnea monitor']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('dc17b1b5-4029-53cf-bad8-701719b2da83', 'medical_english:morphology:atonia:noun:med-morphology-atonia-001', 'ef14b1d5-a00e-5c39-b21b-86d6ae2de28c', 'REM sleep normally brings muscle atonia except in the breathing muscles.', 'atonia', 'During dream sleep the body muscles usually go slack, except the ones used to breathe.', '快速眼动睡眠期除呼吸肌外通常出现肌张力缺失。', array['muscle atonia', 'uterine atonia', 'loss of atonia']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('af5873c1-7eec-54c6-a641-a695c6f10c7b', 'medical_english:morphology:subacute:adjective:med-morphology-subacute-001', '5468170d-9465-5567-838c-b8a5e36c6216', 'A subacute cough lasting three weeks was reviewed in clinic.', 'subacute', 'A cough that had lasted three weeks, neither sudden nor months-long, was checked in clinic.', '持续三周的亚急性咳嗽在门诊复查。', array['subacute cough', 'subacute course', 'subacute thyroiditis']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('8767fd9f-804c-5761-ad48-628aa723a773', 'medical_english:morphology:epidemic:noun:med-morphology-epidemic-001', 'c024a32f-9839-5a21-910e-bac44538e425', 'An influenza epidemic filled the pediatric ward in January.', 'epidemic', 'A sharp community wave of flu filled the children''s ward in January.', '一月的流感流行挤满了儿科病房。', array['influenza epidemic', 'epidemic outbreak', 'control the epidemic']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('e8dfab24-47ad-5b55-a0b0-50d3bb1d4ec9', 'medical_english:morphology:endemic:adjective:med-morphology-endemic-001', 'ea910655-c361-5b51-90bc-42c300685d8b', 'Malaria remains endemic in several tropical regions.', 'endemic', 'Malaria is still always present among people in several hot, wet regions.', '疟疾在若干热带地区仍呈地方性流行。', array['endemic disease', 'endemic area', 'remain endemic']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('148f15d2-5e8e-5d44-a077-43f0c488312d', 'medical_english:morphology:antigen:noun:med-morphology-antigen-001', 'e9e4d315-965b-5bc6-9841-e91dc616fc75', 'The rapid test detects influenza antigen in a nasal swab.', 'antigen', 'The quick test looks for a flu marker in a sample from the nose.', '快速检测从鼻拭子中检测流感抗原。', array['surface antigen', 'antigen test', 'foreign antigen']::text[], 'laboratory_report', 'original_example', null, null, null, null),
  ('25541a8d-a8cd-5d2c-892a-d5cf2e8c28d1', 'medical_english:morphology:antibody:noun:med-morphology-antibody-001', 'aca4631d-b369-56e3-a966-e29614bb70af', 'A positive antibody test showed past exposure rather than acute infection.', 'antibody', 'Finding the defense protein meant earlier contact, not necessarily a new infection right now.', '抗体阳性提示既往暴露，而不是急性感染。', array['antibody titer', 'neutralizing antibody', 'antibody test']::text[], 'laboratory_report', 'original_example', null, null, null, null),
  ('7d62df9b-f245-5566-9ba6-92e18fc65d12', 'medical_english:morphology:immunoglobulin:noun:med-morphology-immunoglobulin-001', '64c47718-fe86-5831-800e-02655b81814a', 'Serum immunoglobulin G was measured after repeated sinus infections.', 'immunoglobulin', 'The main antibody protein in blood was checked after many sinus infections.', '反复鼻窦感染后检测血清免疫球蛋白 G。', array['immunoglobulin G', 'intravenous immunoglobulin', 'immunoglobulin level']::text[], 'laboratory_report', 'original_example', null, null, null, null),
  ('a68c878a-d137-5672-84b1-782fd13c61f3', 'medical_english:morphology:phagocyte:noun:med-morphology-phagocyte-001', '87ee9294-14b2-5160-aa88-60b18b0ffbf9', 'A phagocyte can engulf bacteria and then digest them.', 'phagocyte', 'An eating cell can take bacteria inside and then break them down.', '吞噬细胞可以吞入细菌并加以消化。', array['professional phagocyte', 'phagocyte function', 'circulating phagocyte']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('4efb499a-a3a5-5241-a8fa-542bb457042b', 'medical_english:morphology:degeneration:noun:med-morphology-degeneration-001', 'bb44bc2c-61a5-5698-a2e9-a9ab53d0ad9c', 'Age-related degeneration of cartilage can narrow a joint space.', 'degeneration', 'Wear-and-tear loss of cartilage quality can make the gap in a joint look narrower.', '年龄相关的软骨变性可使关节间隙变窄。', array['fatty degeneration', 'disc degeneration', 'degeneration of cartilage']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('c0ec1e65-03ea-5e98-a335-7de3d5f9c77b', 'medical_english:morphology:malfunction:noun:med-morphology-malfunction-001', '56fb982b-c55c-5108-a6ea-fdbfc1738a06', 'Valve malfunction can let blood leak backward into the atrium.', 'malfunction', 'If a heart valve does not work properly, blood may leak back into the upper chamber.', '瓣膜功能障碍可使血液反流入心房。', array['organ malfunction', 'valve malfunction', 'device malfunction']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('caaab1f6-4fc4-5c1b-aafc-6f6910582857', 'medical_english:morphology:malnutrition:noun:med-morphology-malnutrition-001', '8d3efc58-df59-55a4-a307-2e5362a6d613', 'Wound healing slowed because of protein-energy malnutrition.', 'malnutrition', 'The wound closed more slowly because the body was not getting enough protein and energy.', '蛋白质-能量营养不良使伤口愈合变慢。', array['protein-energy malnutrition', 'severe malnutrition', 'risk of malnutrition']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('811645ad-6f11-507b-b1f3-16dc6a40aa28', 'medical_english:morphology:sublingual:adjective:med-morphology-sublingual-001', '1cc9ba6a-80a6-5211-9375-0ba8d27cbe8a', 'Nitroglycerin was given by the sublingual route for chest pain.', 'sublingual', 'The chest-pain tablet was placed under the tongue so it could be absorbed there.', '胸痛时经舌下途径给予硝酸甘油。', array['sublingual tablet', 'sublingual gland', 'sublingual route']::text[], 'clinical_guideline', 'original_example', null, null, null, null),
  ('e4397116-576c-5f47-85f7-dbf6aa41ccea', 'medical_english:morphology:epiglottis:noun:med-morphology-epiglottis-001', '0f4b8699-00b9-5028-a357-5fc67676f1b0', 'The epiglottis folds down during swallowing to protect the larynx.', 'epiglottis', 'The small flap above the voice box bends down while you swallow so food stays out of the airway.', '吞咽时会厌下折，保护喉入口。', array['leaf-shaped epiglottis', 'swollen epiglottis', 'tip of the epiglottis']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('519a8c72-a378-5fe1-b8fa-ee5adfb08dda', 'medical_english:morphology:peristalsis:noun:med-morphology-peristalsis-001', 'd72695cf-7772-530c-a44f-223b6ce6a90d', 'Normal peristalsis pushes chyme from the stomach into the duodenum.', 'peristalsis', 'Wave-like squeezing moves the partly digested food from the stomach into the first part of the small bowel.', '蠕动把食糜从胃推进十二指肠。', array['intestinal peristalsis', 'reduced peristalsis', 'peristalsis wave']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('901433f1-1c77-5f73-919d-66167b53f220', 'medical_english:morphology:ingestion:noun:med-morphology-ingestion-001', 'a1a7f106-1e1e-5a47-bc75-758974012b34', 'Accidental ingestion of the cleaning liquid occurred at home.', 'ingestion', 'The cleaning liquid was swallowed by mistake at home.', '清洁液在家中被误服摄入。', array['oral ingestion', 'accidental ingestion', 'ingestion of tablets']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('bf99b92e-0869-565b-836f-63f04c4e23a1', 'medical_english:morphology:cardiac:adjective:med-morphology-cardiac-001', 'f666d711-2e73-58ab-bdf9-c648b98bac57', 'Serial cardiac enzymes were drawn after the episode of chest pressure.', 'cardiac', 'Heart-injury blood tests were taken after the spell of tightness in the chest.', '胸闷发作后抽了心肌酶。', array['cardiac arrest', 'cardiac output', 'cardiac enzyme']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('7705f204-6a1a-54ac-8763-d8e577901650', 'medical_english:morphology:paralysis:noun:med-morphology-paralysis-001', '178fe9ff-2876-5251-9131-b0092a3de242', 'Sudden paralysis of the right arm required urgent imaging.', 'paralysis', 'The right arm suddenly could not move, so emergency pictures of the brain and spine were needed.', '右臂突然瘫痪，需紧急影像检查。', array['flaccid paralysis', 'facial paralysis', 'paralysis of the arm']::text[], 'medical_record', 'original_example', null, null, null, null)
